  filter(RFoffset %% 3 != 0)

####Collating results of simulated splice events
#Mapping txID_coords back to predicted effects (exon skipping/inclusion & intron retention/splicing)
exons_cons <- exons %>%
  select(geneSym, geneID, txID, exNo, totalExNo, strand, geneType, txType, exType, intronCoords.upst, coords, intronCoords.downst) %>%
  mutate(txID_coords = paste0(txID, "_", coords)) %>%
  left_join(., (exons_CE %>% select(txID_coords, NMDstat.ex = NMD.stat.pair))) %>%
  mutate(
    #effect of exon inclusion/skipping (L3 = effect on specific transcript)
    exTxEff_L3 = case_when(
      !geneType %in% c("protein_coding") ~ "nonCodingGene",
      !exType %in% c("FCE","ICE","LCE") ~ "nonCodingEx", 
      txID_coords %in% c(exons.PTC$txID_coords, exons.sjPTC$txID_coords) ~ "NMD.PTC", #NMD via PTC when included
      txID_coords %in% c(exons.ifsNMD$txID_coords) ~ "NMD.IncFS", #NMD via frameshifting when included
      txID_coords %in% c(exons.sfsNMD$txID_coords) ~ "NMD.SkipFS", #NMD via frameshifting when excluded
      txID_coords %in% c(exons.ICE.altCT$txID_coords) ~ "aCT.ICE", #alt. C-terminus via frameshifting
      txID_coords %in% c(exons.LCE.altCT$txID_coords) ~ "aCT.LCE", #alt. C-terminus via alternative last coding exon
      txID_coords %in% c(exons.ICE.CDSlost$txID_coords) ~ "CDSinframe", #gain/loss of CDS without frameshifting or NMD
      exType == "FCE" ~ "FCE.loss", #start position lost
      TRUE ~ "noAnno" #likely due to incomplete CDSes
    )
  ) %>%
  mutate( #tie-breaker, when necessary, for later (preference goes NMD -> altered coding sequence -> start lost -> non-coding exon)
    exTxEff_L3 = factor(exTxEff_L3, levels = c("nonCodingGene", "NMD.PTC", "NMD.IncFS", "NMD.SkipFS", "aCT.ICE", "aCT.LCE", "CDSinframe", "FCE.loss","nonCodingEx", "noAnno"))
  ) %>%
  left_join(., (exons_RI %>% select(txID_coords, NMDstat.dnInt = NMD.stat.pair))) %>%
  mutate(
    #effect of intron retention/splicing (L2 = effect on specific transcript)
    dnIntTxEff_L2 = case_when(
      !geneType %in% c("protein_coding") ~ "nonCodingGene",
      !exType %in% c("FCE","ICE") ~ "notInCDS",
      txID_coords %in% c(introns.rNMD$txID_coords) ~ "NMD.spl", #NMD when spliced out
      txID_coords %in% c(introns.NMD$txID_coords) ~ "NMD.ret", #NMD when retained
      txID_coords %in% c(introns.insAA$txID_coords) ~ "insCDS.ret", #sequence inserted/removed, no NMD, no frameshifting
      txID_coords %in% c(introns.insAA_FS$txID_coords) ~ "insCDS_FS.ret", #sequence inserted/removed with frameshifting, no NMD
      txID_coords %in% c(introns.intronicStop$txID_coords) ~ "intronicStop.ret", #NMD via PTC when retained, no NMD
      TRUE ~ "noAnno" #remainder (usually due to incomplete CDS transcripts)
    )
  ) %>%
  mutate(#tie-breaker, when necessary, for later (preference goes NMD -> altered coding sequence -> non-coding exon)
    dnIntTxEff_L2 = factor(dnIntTxEff_L2, levels = c("nonCodingGene", "NMD.spl", "NMD.ret", "insCDS.ret", "insCDS_FS.ret", "intronicStop.ret", "noAnno", "notInCDS"))
  )

#effect of exon inclusion/skipping (L2 = effect when considering flanking exons)
exons_cons_L2 <- exons_cons %>%
  mutate(NFtag = ifelse(exTxEff_L3 == "noAnno", TRUE, FALSE)) %>%  #de-prioritise incomplete CDS
  mutate(NCE = ifelse(!exType %in% c("FCE","ICE","LCE"), TRUE, FALSE)) %>% #de-prioritise non-coding exons
  mutate(coords.L2 = paste(geneID, intronCoords.upst, coords, intronCoords.downst, sep = "_")) %>%
  select(coords.L2, NCE, exTxEff_L2 = exTxEff_L3, NFtag) %>%
  group_by_all() %>%
  summarise(n = n(), .groups = "drop") %>% 
  arrange(coords.L2, NCE, NFtag, -n, exTxEff_L2) %>%
  filter(!duplicated(coords.L2)) #keep most common outcome

#effect of exon inclusion/skipping (L1 = effect when considering only the exon itself)
exons_cons_L1 <- exons_cons %>%
  mutate(NFtag = ifelse(exTxEff_L3 == "noAnno", TRUE, FALSE)) %>%
  mutate(NCE = ifelse(!exType %in% c("FCE","ICE","LCE"), TRUE, FALSE)) %>%
  select(geneSym, NCE, coords, exTxEff_L1 = exTxEff_L3, NFtag) %>%
  group_by_all() %>%
  summarise(n = n(), .groups = "drop") %>%
  arrange(geneSym, coords, NCE, NFtag, -n, exTxEff_L1) %>%
  filter(!duplicated(paste(geneSym, coords, sep = "_"))) #keep most common outcome

#effect of intron retention/splicing (L1 = effect when considering only the intron itself)
introns_primaryCons <- exons_cons %>%
  mutate(NFtag = ifelse(dnIntTxEff_L2 == "noAnno", TRUE, FALSE)) %>%
  mutate(NCE = ifelse(!exType %in% c("FCE","ICE","LCE"), TRUE, FALSE)) %>%
  select(geneSym, intronCoords.downst, NCE, dnIntTxEff_L1 = dnIntTxEff_L2, NFtag) %>%
  group_by_all() %>%
  summarise(n = n(), .groups = "drop") %>%
  arrange(geneSym, intronCoords.downst, NCE, NFtag, -n, dnIntTxEff_L1) %>%
  filter(!duplicated(paste0(geneSym, "_", intronCoords.downst))) #keep most common outcome

#insert higher level consequences back
simulTX <- exons_cons %>%
  mutate(coords.L2 = paste(geneID, intronCoords.upst, coords, intronCoords.downst, sep = "_")) %>%
  left_join(., exons_cons_L2 %>% select(coords.L2, exTxEff_L2)) %>%
  left_join(., exons_cons_L1 %>% select(geneSym, coords, exTxEff_L1)) %>%
  left_join(., introns_primaryCons %>% select(geneSym, intronCoords.downst, dnIntTxEff_L1)) %>%
  select(-coords.L2)

#export file
write.table(res.out, "./GENCODEv47_simulatedTx.txt", sep = "\t", row.names = FALSE, quote = FALSE)

