      !exType %in% c("FCE","ICE","LCE") ~ "nonCodingEx",
      txID_coords %in% c(A3.PTC_dist$txID_coords) ~ "PTC_dist", #NMD via PTC in longer exon
      txID_coords %in% c(A3.PTC_prox$txID_coords) ~ "PTC_prox", #NMD via PTC in shorter exon
      txID_coords %in% c(A3.fsNMD_dist$txID_coords) ~ "fsNMD_dist", #NMD via frameshifting in longer exon
      txID_coords %in% c(A3.fsNMD_prox$txID_coords) ~ "fsNMD_prox", #NMD via frameshifting in shorter exon
      txID_coords %in% c(A3.indelCDS$txID_coords) ~ "indelCDS", #in-frame changes to CDS
