  ) %>%
  select(geneSym, geneID, txID, exNo, totalExNo, chr, strand, geneType, txType, exType, intronCoords.upst, coords, intronCoords.downst, txID_coords, RFoffset, dist3SS, prox3SS, fixed5SS, NMD.stat.pair, NMD.stat.distVsProx, A3TxEff_L3)

